import Foundation

/// Japanese UI strings, keyed by the Chinese and English pair a call site passes to `L10n.text`.
///
/// The pairs keep one English word from collapsing two meanings into one translation ("Display" the screen and
/// "Display" the verb). Kept out of the call sites so upstream changes to a call site do not conflict with the
/// translation, and so a pair without a translation falls back to English. Regenerate with the catalog script.
extension L10n {
    static func japanese(zh: String, en: String) -> String? {
        JapaneseStrings.table[en + "\u{1F}" + zh]
    }
}

